// ─── File: LoanHexagonalDemo.java ───
// Hexagonal architecture: domain in the center, ports as interfaces, adapters outside.
// The domain imports NOTHING technology-specific. Adapters depend on domain ports.
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class LoanHexagonalDemo {
    private static final Logger log = Logger.getLogger("Loan");
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Wire adapters into the domain (dependency injection does this in Spring).
        LoanRepository repo = new InMemoryLoanRepository();      // outbound adapter
        CreditBureauPort bureau = new StubCreditBureau(760);     // outbound adapter
        ApproveLoanUseCase useCase = new LoanService(repo, bureau); // domain
        LoanController controller = new LoanController(useCase); // inbound adapter

        controller.handleApply("LN-1", "SAV2001", new BigDecimal("500000"));

        // Swap the credit-bureau adapter WITHOUT touching the domain.
        log.info("--- swap credit bureau adapter (score now 620) ---");
        CreditBureauPort bureau2 = new StubCreditBureau(620);
        LoanController controller2 = new LoanController(new LoanService(repo, bureau2));
        controller2.handleApply("LN-2", "CUR3001", new BigDecimal("300000"));
    }
}

// ─── domain/Loan.java (NO framework imports) ───
class Loan {
    final String id, customerId; final BigDecimal amount; String status;
    Loan(String id, String customerId, BigDecimal amount) {
        this.id = id; this.customerId = customerId; this.amount = amount; this.status = "PENDING";
    }
}

// ─── domain/port/in/ApproveLoanUseCase.java (inbound port) ───
interface ApproveLoanUseCase {
    Loan approve(String loanId, String customerId, BigDecimal amount);
}

// ─── domain/port/out/LoanRepository.java (outbound port) ───
interface LoanRepository {
    void save(Loan loan);
    Optional<Loan> findById(String id);
}

// ─── domain/port/out/CreditBureauPort.java (outbound port) ───
interface CreditBureauPort {
    int fetchScore(String customerId);
}

// ─── domain/LoanService.java (pure business rules, depends ONLY on ports) ───
class LoanService implements ApproveLoanUseCase {
    private static final Logger log = Logger.getLogger("Loan");
    private final LoanRepository repo;
    private final CreditBureauPort bureau;
    LoanService(LoanRepository repo, CreditBureauPort bureau) { this.repo = repo; this.bureau = bureau; }

    @Override public Loan approve(String loanId, String customerId, BigDecimal amount) {
        Loan loan = new Loan(loanId, customerId, amount);
        int score = bureau.fetchScore(customerId);      // outbound port call
        // Business rule — lives in the domain, framework-agnostic.
        if (score >= 700) { loan.status = "APPROVED"; }
        else { loan.status = "REJECTED"; }
        repo.save(loan);                                 // outbound port call
        log.info(() -> "Loan " + loanId + " for " + customerId + " score=" + score
                + " → " + loan.status);
        return loan;
    }
}

// ─── adapter/in/web/LoanController.java (inbound adapter — drives the use case) ───
class LoanController {
    private final ApproveLoanUseCase useCase;
    LoanController(ApproveLoanUseCase useCase) { this.useCase = useCase; }
    void handleApply(String loanId, String customerId, BigDecimal amount) {
        // In Spring: @PostMapping; deserialize JSON; then call the port.
        useCase.approve(loanId, customerId, amount);
    }
}

// ─── adapter/out/InMemoryLoanRepository.java (outbound adapter; JPA in prod) ───
class InMemoryLoanRepository implements LoanRepository {
    private final Map<String, Loan> store = new HashMap<>();
    @Override public void save(Loan loan) { store.put(loan.id, loan); }
    @Override public Optional<Loan> findById(String id) { return Optional.ofNullable(store.get(id)); }
}

// ─── adapter/out/StubCreditBureau.java (outbound adapter; HTTP in prod) ───
class StubCreditBureau implements CreditBureauPort {
    private final int score;
    StubCreditBureau(int score) { this.score = score; }
    @Override public int fetchScore(String customerId) { return score; }
}

// ─── config/BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
